-- 2026-11-06: add SecretShield and CodeFlow Mapper to the VS Code extensions tab of /winstore,
-- after the Windows apps and before the other extensions. Run after 2026-11-04-store-apps.sql.

begin;

-- the store_apps table from 2026-11-04 may predate the 'vscode' kind
alter table portfolio.store_apps drop constraint if exists store_apps_kind_check;
alter table portfolio.store_apps add constraint store_apps_kind_check check (kind in ('app', 'vscode', 'extension'));

update portfolio.store_apps set sort = sort + 2 where kind = 'extension';

insert into portfolio.store_apps (sort, slug, name, kind, category, publisher, tagline, about, version, released, size_label, requires, tone, logo, download, install, steps, downloads, links, features, system_slug) values
  (4, 'secretshield', 'SecretShield', 'vscode', 'VS Code · Linters', null, 'Catch leaked keys and tokens before they ever leave your machine.', 'SecretShield scans your workspace for secrets entirely on your machine: no uploads, no LLM calls and no telemetry, with every secret value masked in its output. It sorts findings into three phases (general exposure, highly restricted credentials and unprotected sensitive files), checks with Git itself whether those files are tracked, ignored or already in history, and installs a pre-push hook that blocks commits carrying restricted secrets.', '0.3.0', '4 Nov 2026', null, 'VS Code · runs fully offline', 'pink', '{"src":"/images/logos/secretshield.webp","width":96,"height":96,"alt":"SecretShield icon"}'::jsonb, '{"label":"Install from the Marketplace","file":"MohammadRamiz.secretshield","href":"https://marketplace.visualstudio.com/items?itemName=MohammadRamiz.secretshield"}'::jsonb, 'code --install-extension MohammadRamiz.secretshield', null, null, '[{"label":"Visual Studio Marketplace","href":"https://marketplace.visualstudio.com/items?itemName=MohammadRamiz.secretshield"},{"label":"Open in VS Code","href":"vscode:extension/MohammadRamiz.secretshield"}]'::jsonb, array['Three-phase classification: exposure, restricted credentials, file hygiene', 'Pre-push hook that scans outgoing commits and blocks restricted secrets', 'Squiggles, hovers and quick fixes: move to an env variable, add to .gitignore, suppress with a reason']::text[], null),
  (5, 'codeflow-mapper', 'CodeFlow Mapper', 'vscode', 'VS Code · Python', null, 'See how a Python codebase actually runs, as an interactive flowchart.', 'CodeFlow Mapper statically analyses a Python project from its entry points and draws an interactive map of how it runs, without ever importing or executing your code. It understands FastAPI first, plus Flask, Django, Celery and plain scripts: routes, middleware, dependency injection and calls across files, with each edge labelled by how sure it is.', '0.1.0', '4 Nov 2026', null, 'VS Code 1.85+ · Python 3.8+', 'blue', '{"src":"/images/logos/codeflow-mapper.webp","width":96,"height":96,"alt":"CodeFlow Mapper icon"}'::jsonb, '{"label":"Install from the Marketplace","file":"MohammadRamiz.codeflow-mapper","href":"https://marketplace.visualstudio.com/items?itemName=MohammadRamiz.codeflow-mapper"}'::jsonb, 'code --install-extension MohammadRamiz.codeflow-mapper', null, null, '[{"label":"Visual Studio Marketplace","href":"https://marketplace.visualstudio.com/items?itemName=MohammadRamiz.codeflow-mapper"},{"label":"Open in VS Code","href":"vscode:extension/MohammadRamiz.codeflow-mapper"}]'::jsonb, array['Finds entry points: FastAPI routes, Flask blueprints, Django URLs, Celery tasks, scripts', 'Overview, execution-flow, function explorer and impact views, with double-click to jump to source', 'Exports to PNG, SVG, Mermaid, JSON and Markdown; optional AI explanations are off by default']::text[], null)
on conflict (slug) do nothing;

commit;
